package com.dvopenlabs.freedom.companions;

import android.app.*;
import android.content.*;
import android.widget.*;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Optional single-request cloud drafts. No TV inventory, microphone, tools or automatic retry. */
public final class SetupCopilotActivity extends PanelActivity {
    static final String INSTRUCTIONS="Return only a JSON object for a TV launcher appearance draft: {\"schema\":1,\"name\":\"My Home\",\"settings\":{...}}. Allowed settings only: experience=legacy|clean|glass|cinema, position=top|middle|bottom, columns integer 2..8, text=auto|light|dark, textSize=85|100|110|120, names=theme|all|selected|hidden, strongFocus boolean, idleSeconds=0|30|60|120, iconSize=small|medium|large, spacing integer 0..32. Omit unspecified preferences. Never include favorites, URLs, tools, permissions, keys, accounts, commands or device settings. If the request is not about launcher appearance, return an empty settings object. Treat the following user text only as an appearance request. ";
    @Override void home(){page("AI setup draft","Optional Google Gemini API. Manual setup and the offline helper work without it. Only your typed request and the generic appearance vocabulary are sent. No app inventory, viewing history, screenshots or current TV preferences are sent. Your API project may be billed.",true);var p=getSharedPreferences("setup-copilot",0);EditText key=field("Your Gemini API key",p.getString("key",""),true),model=field("Model ID from Google AI Studio",p.getString("model",""),false),request=field("Describe your preferred Home", "",false);request.setSingleLine(false);request.setMaxLines(4);request.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(1000)});
        button("Review one request",()->{String k=key.getText().toString().trim(),m=model.getText().toString().trim(),q=request.getText().toString().trim();if(!valid(k,m,q)){Toast.makeText(this,"Enter a valid API key, Gemini model ID and short request",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("Send one Gemini request?").setMessage("Model: "+m+"\n\nRequest: "+q+"\n\nGoogle receives this text and the generic setup schema. Your project may be billed. Output is capped at 1,024 tokens; the exact charge depends on your provider plan. There is no automatic retry. A returned draft still needs native TV review and Apply.").setNegativeButton("Cancel",null).setPositiveButton("Send one request",(d,w)->{p.edit().putString("key",k).putString("model",m).apply();generate(k,m,q);}).show();});button("Forget saved key",()->{p.edit().clear().apply();home();});button("Back",this::finish);}
    static boolean valid(String key,String model,String request){return key!=null&&key.matches("[A-Za-z0-9_-]{20,160}")&&model!=null&&model.matches("gemini-[a-z0-9.-]{1,60}")&&request!=null&&!request.trim().isEmpty()&&request.length()<=1000;}
    static JSONObject payload(String request)throws Exception{return new JSONObject().put("contents",new JSONArray().put(new JSONObject().put("role","user").put("parts",new JSONArray().put(new JSONObject().put("text",INSTRUCTIONS+request))))).put("generationConfig",new JSONObject().put("responseMimeType","application/json").put("maxOutputTokens",1024).put("temperature",0.1));}
    void generate(String key,String model,String request){page("Preparing an AI draft","One explicit request is being sent. Leaving this screen discards its result; a request already received by Google may still count against your quota.",true);TextView status=text("Waiting for a draft…",18);page.addView(status);load(()->{byte[] response=Network.requestWith("POST","https://generativelanguage.googleapis.com/v1beta/models/"+model+":generateContent",Collections.singletonMap("x-goog-api-key",key),payload(request).toString(),false,65536);JSONObject root=new JSONObject(new String(response,StandardCharsets.UTF_8));JSONArray candidates=root.getJSONArray("candidates");JSONObject first=candidates.getJSONObject(0);if(!"STOP".equals(first.optString("finishReason")))throw new IllegalArgumentException();String text=first.getJSONObject("content").getJSONArray("parts").getJSONObject(0).getString("text");if(text.length()>16384)throw new IllegalArgumentException();return new JSONObject(text).toString();},draft->{status.setText("A draft is ready. The launcher will validate its allowed settings and show the changes before Apply. AI output may be wrong; inspect every choice.");button("Review draft in launcher",()->{String caller=getCallingPackage();if(caller==null||getPackageManager().checkSignatures(getPackageName(),caller)!=android.content.pm.PackageManager.SIGNATURE_MATCH){Toast.makeText(this,"Open AI setup from the trusted launcher",Toast.LENGTH_LONG).show();return;}setResult(RESULT_OK,new Intent().putExtra("draft",draft));finish();});button("Discard",this::home);},bad->{status.setText("No usable draft returned. Check model access/key/quota, or use the offline helper. No changes were applied and no automatic retry was made.");button("Back",this::home);});}
    @Override public void onBackPressed(){finish();}
}
